import (
	context "context"
	fern "github.com/multi-content-type-examples/fern"
	fernclient "github.com/multi-content-type-examples/fern/client"
)

client := fernclient.NewClient()
response, err := client.Clients.Create(
	context.TODO(),
	&fern.ClientRequest{
		Client: &fern.Client{
			Name:  "Acme Corp",
			Email: "contact@acme.com",
		},
	},
)
